       "exact_text": "open_gripper()\nlook_at_region(\"sink_basin\")\no = observe(\"wrist_cam\")\nsponge = None\nfor d in o[\"detections\"]:\n    if d[\"category\"] == \"sponge\":\n        sponge = d\n        break\nif sponge is None:\n    found = False\n    handle_info = None\n    push_dir_info = None\n    for region in [\"drawer_unit:0\", \"drawer_unit:1\"]:\n        h = handle_for_region(region)\n        if h is None:\n            continue\n        ro = open_drawer(h[\"position_m\"], h[\"pull_dir\"])\n        if not ro[\"ok\"]:\n            continue\n        look_at_region(region)\n        o2 = observe(\"wrist_cam\")\n        sp = None\n        for d in o2[\"detections\"]:\n            if d[\"category\"] == \"sponge\":\n                sp = d\n                break\n        if sp is not None:\n            sponge = sp\n            handle_info = h\n            push_dir_info = [-h[\"pull_dir\"][0], -h[\"pull_dir\"][1], -h[\"pull_dir\"][2]]\n            found = True\n            break\n        push_dir = [-h[\"pull_dir\"][0], -h[\"pull_dir\"][1], -h[\"pull_dir\"][2]]\n        rc = close_drawer(h[\"position_m\"], push_dir)\n    if not found:\n        help(\"sponge not found\", kind=\"search_incomplete\")\nopen_gripper()\nrpick = pick(sponge[\"position_m\"], \"sponge\", grasp=\"top\")\nif not rpick[\"ok\"]:\n    help(\"pick failed \" + rpick[\"reason\"], kind=\"safety\")\nif handle_info is not None:\n    rclose = close_drawer(handle_info[\"position_m\"], push_dir_info)\nbowl_list = tracks(\"bowl\")\nif not bowl_list:\n    help(\"bowl not perceived\", kind=\"perception\")\nbowl_pos = bowl_list[0][\"position_m\"]\nrscrub = scrub(bowl_pos, seconds=3.0, force=4.0)\nif not rscrab[\"ok\"]:\n    help(\"scrub failed \" + rscrab[\"reason\"], kind=\"safety\")\ndone()"
